import React, { useState, useEffect, useRef } from "react";
import ProductRow from "./ProductRow";

export default function StorageTransfer({
  categories,
  storages,
  onAddTransfer,
  onRemoveTransfer,
  onUpdateTransfer,
  transfers = []
}) {
  const [selectedToStorage, setSelectedToStorage] = useState("");

  const handleToStorageSelect = (storageId) => {
    setSelectedToStorage(storageId);
  };

  const addProductRow = () => {
    const newProduct = {
      id: Date.now() + Math.random(),
      category: "",
      quantity: "",
      weight: "",
      StorageID: "", // This will be the source storage (where product currently is)
      storageName: ""
    };
    onAddTransfer(newProduct);
  };

  const removeProductRow = (prodIdx) => {
    onRemoveTransfer(prodIdx);
  };

  const updateProductField = (prodIdx, field, value) => {
    const updatedProduct = { ...transfers[prodIdx], [field]: value };
    onUpdateTransfer(updatedProduct, prodIdx);
  };

  return (
    <div className="storage-transfer-section">
      <div className="section-header">
        <h3>Storage Transfers (Relocate Products)</h3>
        <p className="section-description">
          Use leftover truck capacity to relocate products between storages
        </p>
      </div>

      <div className="transfer-block">
        {/* Destination Storage Selection */}
        <div className="transfer-header">
          <div className="transfer-cell">
            <div className="storage-search-wrapper" ref={suggestionRef}>
              <input
                className="storage-input"
                type="text"
                placeholder="Type to search destination storage..."
                value={toStorageSearchTerm}
                onChange={(e) => handleToStorageSearch(e.target.value)}
              />
              {toStorageSuggestions.length > 0 && (
                <ul className="suggestions-list">
                  {toStorageSuggestions.map((storage) => (
                    <li
                      key={storage.id}
                      onClick={() => handleToStorageSelect(storage)}
                    >
                      {storage.name}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
          <div className="remove-transfer-cell">
            <button className="btn remove-transfer-btn">×</button>
          </div>
        </div>

        {/* Product Rows */}
        <div className="product-rows">
          {transfers.map((product, index) => (
            <ProductRow
              key={product.id}
              pr={product}
              categories={categories}
              storages={storages}
              onChange={(field, value) => updateProductField(index, field, value)}
              onRemove={() => removeProductRow(index)}
            />
          ))}
        </div>

        {/* Add Product Row Button */}
        <div className="add-product-row">
          <button className="btn add-product-btn" onClick={addProductRow}>
            + Add Product
          </button>
        </div>
      </div>
    </div>
  );
}
